-- Catalogo completo de tratas GDEBA extraido de buscarTratas.
-- Inserta solo codigos inexistentes; no actualiza ni elimina filas existentes.
-- IOMA0010 estaba duplicada en la respuesta: se conserva la version con estado ALTA.
SET NOCOUNT ON;
SET XACT_ABORT ON;

IF OBJECT_ID(N'dbo.TratasGdeba', N'U') IS NULL
    THROW 50000, N'No existe la tabla dbo.TratasGdeba en la base seleccionada.', 1;

DECLARE @Origen TABLE
(
    Codigo nvarchar(50) NOT NULL PRIMARY KEY,
    Descripcion nvarchar(500) NULL,
    AcronimoGedo nvarchar(50) NULL,
    EsAutomatica bit NULL,
    EsTrataManual bit NULL,
    Estado nvarchar(100) NULL,
    IdTrataGdeba nvarchar(100) NULL,
    TipoReservaDescripcion nvarchar(500) NULL,
    TipoReservaId nvarchar(100) NULL,
    TipoReservaDescripcionTipoReserva nvarchar(500) NULL
);







BEGIN TRY
    BEGIN TRANSACTION;

        Id, Codigo, Descripcion, AcronimoGedo, EsAutomatica, EsTrataManual, Estado, IdTrataGdeba,
        TipoReservaDescripcion, TipoReservaId, TipoReservaDescripcionTipoReserva
    )
    SELECT
        NEWID(), origen.Codigo, origen.Descripcion, origen.AcronimoGedo, origen.EsAutomatica, origen.EsTrataManual, origen.Estado, origen.IdTrataGdeba,
        origen.TipoReservaDescripcion, origen.TipoReservaId, origen.TipoReservaDescripcionTipoReserva
    FROM @Origen AS origen
    WHERE NOT EXISTS
    (
        SELECT 1
        FROM dbo.TratasGdeba AS destino
        WHERE destino.Codigo = origen.Codigo
    );

    DECLARE @Insertadas int = @@ROWCOUNT;

    COMMIT TRANSACTION;

    SELECT @Insertadas AS TratasInsertadas, COUNT(*) AS TratasEnCatalogo
    FROM @Origen;
END TRY
BEGIN CATCH
    IF XACT_STATE() <> 0
        ROLLBACK TRANSACTION;

    THROW;
END CATCH;
